import {accountReady} from './account-client.js';
const $=id=>document.getElementById(id),el=(tag,text)=>{const n=document.createElement(tag);n.textContent=text;return n;};
let clerk,offset=0,next=null,busy=false;
async function request(body,query=''){clerk??=await accountReady();const token=await clerk.session?.getToken();if(!token)throw Error('Sign in with your owner account.');const r=await fetch('/api/recipe-contributors'+query,{method:body?'POST':'GET',headers:{Authorization:`Bearer ${token}`,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,cache:'no-store'});const data=await r.json();if(!r.ok){if([401,403].includes(r.status))$('invitation-workspace').hidden=true;throw Error(data.error);}return data;}
async function run(fn){if(busy)return;busy=true;try{await fn();}catch(e){$('invitation-status').textContent=e.message;$('invitation-status').focus();}finally{busy=false;}}
function button(text,fn){const b=el('button',text);b.type='button';b.addEventListener('click',()=>run(fn));return b;}
async function list(){const data=await request(null,'?offset='+offset);next=data.nextOffset;$('invitation-list').replaceChildren();for(const r of data.items){const card=el('article','');card.className='catalog-card';card.append(el('h3',r.account_id),el('p',`${r.status} · invited ${r.invited_at} · expires ${r.expires_at}`),el('p',`Invited by ${r.invited_by}${r.revoked_by?' · revoked by '+r.revoked_by:''}`));if(r.status==='active')card.append(button('Revoke invitation',async()=>{await request({action:'revoke',identifier:r.account_id});await list();$('invitation-status').textContent='Invitation revoked.';}));card.append(button('View private history',async()=>{const result=await request(null,'?account='+encodeURIComponent(r.account_id));$('invitation-audit').replaceChildren(el('h2','Invitation history'),...result.events.map(e=>el('p',`${e.created_at} · ${e.action} · ${e.actor_id}${e.expires_at?' · expires '+e.expires_at:''}`)));}));card.append(button('Reconcile deleted account',async()=>{await request({action:'account-deleted',identifier:r.account_id});await list();$('invitation-status').textContent='Account deletion recorded. Recipe records retained for owner review.';}));$('invitation-list').append(card);}if(!data.items.length)$('invitation-list').append(el('p','No invitations yet.'));$('invitation-workspace').hidden=false;$('invitations-previous').disabled=offset===0;$('invitations-next').disabled=next===null;}
$('invite-form').addEventListener('submit',e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target);const result=await request({action:'invite',identifier:f.get('identifier'),expiresAt:f.get('expiresAt')+'T23:59:59.000Z'});await list();$('invitation-status').textContent=result.duplicate?'This account already has an active invitation.':'Invitation recorded. No email sent.';});});
$('invitations-previous').addEventListener('click',()=>run(async()=>{offset=Math.max(0,offset-20);await list();}));$('invitations-next').addEventListener('click',()=>run(async()=>{if(next!==null){offset=next;await list();}}));
await run(async()=>{await list();$('invitation-status').textContent='Owner access verified. Invitations stay private.';});

if(clerk){let sessionId=clerk.session?.id;clerk.addListener(({session})=>{if(session?.id!==sessionId){sessionId=session?.id;$('invitation-workspace').hidden=true;$('invitation-list').replaceChildren();$('invitation-audit').replaceChildren();$('invitation-status').textContent='Account changed. Reload to verify owner access.';}});}
